def validate_device_id(device_id):
    """
    Validates an operator-entered device ID for a regional electricity grid SCADA system.

    Parameters:
    device_id (str): The device ID to be validated.

    Returns:
    tuple: A tuple containing a boolean indicating if the device ID is valid and the reason for validation.
