    # Check if the device ID is 7 characters long
    if len(device_id) != 7:
        return (False, "Device ID must be 7 characters long.")

    # Check for the presence of the required characters
    if not device_id.isalnum():
        return (False, "Device ID must contain only alphanumeric characters.")

    # Check for the presence of specific characters
    if not device_id.startswith("DEV_") and not device_id.startswith("DEV1"):
        return (False, "Device ID must start with 'DEV_' or 'DEV1'.")

    # If all checks pass, the device ID is valid
    return (True, "Device ID is valid.")

