class SCADAConfigLoader:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config_data = None

    def load_config(self):
        try:
            with open(self.config_file, 'r') as file:
                self.config_data = json.load(file)
        except FileNotFoundError:
            print(f"Error: The configuration file {self.config_file} was not found.")
        except json.JSONDecodeError:
            print(f"Error: Unable to decode JSON data from the configuration file {self.config_file}.")

    def get_device_settings(self, device_id):
