import datetime
import json

class AuditLogger:
    def __init__(self, log_file):
        self.log_file = log_file
        self.init_log()

    def init_log(self):
        self.log_dict = {}
        with open(self.log_file, 'w', encoding='utf-8') as file:
            json.dump(self.log_dict, file, ensure_ascii=False, indent=4)
        self.log_dict = {}

    def log_action(self, action, timestamp=None):
        if timestamp is None:
            timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        if action not in self.log_dict:
            self.log_dict[action] = []
        self.log_dict[action].append({
            'timestamp': timestamp,
            'action': action
        })
        self.write_log()

    def write_log(self):
        with open(self.log_file, 'w', encoding='utf-8') as file:
            json.dump(self.log_dict, file, ensure_ascii=False, indent=4)

# Example usage
